"""Contact sheet rows for substitute teachers."""

# ---
def contact_rows(students):
    if not students:
        raise ValueError("no students for the contact sheet")
    for item in students:
        if not item.email:
            raise ValueError(f"no email for {item.display_name}")
    ordered = sorted(students, key=lambda item: item.display_name)
    wide = max(len(item.display_name) for item in ordered)
    return [_line(item, wide) for item in ordered]

def _line(item, wide):
    name = item.display_name.ljust(wide)
    return f"{name}  {item.section:<8}{item.email}"

