import unittest

from rosterkit.contacts import contact_rows
from rosterkit.models import Student

def make(last, email="x@example.invalid"):
    return Student("1", last, "Pat", "A", email)

class ContactTests(unittest.TestCase):
    def test_sorted_and_aligned(self):
        rows = contact_rows([make("Zed"), make("Longname")])
        self.assertEqual(
            rows,
            [
                "Longname, Pat  A       x@example.invalid",
                "Zed, Pat       A       x@example.invalid",
            ],
        )

    def test_missing_email_names_student(self):
        with self.assertRaises(ValueError) as caught:
            contact_rows([make("Zed", None)])
        self.assertIn("Zed, Pat", str(caught.exception))

    def test_empty_list(self):
        with self.assertRaises(ValueError):
            contact_rows([])
